			// EVENTS can break independently, so each is exercised.
			setSettings({
				...CHROME_DEFAULTS,
				desk_layout: "Top Bar",
				topbar_enabled: 1,
				bottombar_enabled: 1,
				inbox_placement: "Top Bar End",
				user_placement: "Top Bar End",
			});
