				out.dialog = { radius: getComputedStyle(c).borderTopLeftRadius, shadow: getComputedStyle(c).boxShadow };
				try { window.jQuery(document.querySelector(".modal.show")).modal("hide"); } catch (e) { /* teardown */ }
